entries[13503] = { ["name"] = "Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n+15 Stärke\n+15 Beweglichkeit\n+15 Ausdauer\n+15 Intelligenz\n+15 Willenskraft\nBenötigt Alchemie\n(350)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar." }
