entries[13506] = { ["name"] = "Trank der Versteinerung", ["text"] = "Benötigt Stufe 50\nBenutzen: Ihr werdet zu Stein und absorbiert 6000 Schaden aus jeglicher Schadensquelle, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen oder Zauber wirken. Hält 30 sec lang an. (1 Min Abklingzeit)" }
