entries[13508] = { ["name"] = "Auge von Arachnida", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\nBenutzen: Beschwört das Auge von Kilrogg und bindet Eure Sicht daran. Das Auge bewegt sich schnell, ist jedoch sehr zerbrechlich. (1 Min Abklingzeit)\n3 Aufladungen" }
entries[13509] = { ["name"] = "Klammer der Voraussicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\nBenutzen: Kontert das Zauberwirken des Feindes und verhindert 10 sec lang, dass ein Zauber dieser Art der Magie gewirkt werden kann. Führt zu einem hohen Maß an Bedrohung. Es besteht die Chance eines Fehlschlags, wenn das Ziel über Stufe 60 ist. (1 Min Abklingzeit)" }
entries[13510] = { ["name"] = "Fläschchen der Titanen", ["text"] = "Benötigt Stufe 50\nBenutzen: Erhöht die maximale Gesundheit des Spielers 1 hour lang um 400. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[13511] = { ["name"] = "Fläschchen der destillierten Weisheit", ["text"] = "Benötigt Stufe 50\nBenutzen: Erhöht die Intelligenz 1 hour lang um 65. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[13512] = { ["name"] = "Fläschchen der obersten Macht", ["text"] = "Benötigt Stufe 50\nBenutzen: Erhöht die Zaubermacht 1 hour lang um 70. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
