entries[13515] = { ["name"] = "Ramsteins Blitzbolzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 55\nBenutzen: Setzt die Macht des Blitzschlags ein, um allen Feinden um Euch herum 200 Naturschaden zuzufügen. (5 Min Abklingzeit)" }
